from pathlib import Path
import base64, json, html, zipfile

out=Path(__file__).resolve().parents[1]
root=out
(root/'work').mkdir(exist_ok=True)
def data(path):
 p=out/path
 mime={'.svg':'image/svg+xml','.png':'image/png','.jpg':'image/jpeg'}[p.suffix]
 return f'data:{mime};base64,'+base64.b64encode(p.read_bytes()).decode()
def picture(path,alt):
 return f'<img src="{data(path)}" alt="{html.escape(alt)}" width="1536" height="1024">'

frames=[data(Path(f'designs/matrix-{i}.svg')) for i in range(1,4)]
prompt='''Edit the supplied Strangelove-inspired poster into a closing-slide image. Preserve the identity and recognisable face of the existing rider, his pose, the bomb with H(θ) on its side, and the black-and-white film aesthetic. Remove the title and subtitle lettering while retaining the H(θ) marking on the bomb. Rebalance the rider and bomb to work as the focal point of a 3:2 landscape composition. Keep the sky simple. No additional people, captions, equations, symbols, icons, maps or labels. Preserve the original mood; avoid making it more spectacular or cluttered.'''
with (root/'work/design-board-data.json').open('w') as f:
 json.dump({'matrix_frames':frames,'optional_closing_prompt':prompt},f,ensure_ascii=False)

styles='''
:root{--paper:#f8f6f0;--ink:#20272d;--muted:#5b666e;--blue:#347eab;--rule:#d8d9d4}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:18px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1250px;margin:auto;padding:55px 35px 70px}h1{font-size:clamp(36px,5vw,62px);line-height:1.05;letter-spacing:-.04em;margin:.2em 0}h2{font-size:30px;line-height:1.15;margin:0 0 20px;letter-spacing:-.025em}h3{font-size:19px;line-height:1.3;margin:13px 0 5px}p{max-width:70ch;margin:0 0 18px}a{color:var(--blue)}header{max-width:850px;padding-bottom:35px}.eyebrow{font-size:13px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}.intro{font-size:22px;line-height:1.45}.hero{display:grid;grid-template-columns:1.35fr 1fr;gap:35px;align-items:center;padding:25px 0 45px}.hero img{display:block;width:100%;height:auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.wide{grid-column:1/-1}.study img{display:block;width:100%;height:auto;aspect-ratio:3/2;object-fit:contain;border:1px solid var(--rule)}.study p{font-size:16px;color:var(--muted)}section{padding:35px 0;border-top:1px solid var(--rule)}.palette{display:flex;gap:25px;flex-wrap:wrap;margin:25px 0}.swatch{display:flex;align-items:center;gap:10px;font-size:14px}.swatch i{display:block;width:30px;height:30px;border:1px solid #ccc}.ladder{display:grid;grid-template-columns:minmax(0,2fr) minmax(220px,1fr);gap:25px;align-items:start}.ladder img{display:block;width:100%;height:auto;aspect-ratio:3/2;object-fit:contain;border:1px solid var(--rule)}button{font:inherit;border:1px solid var(--ink);padding:10px 13px;cursor:pointer;background:transparent;color:var(--ink)}button[aria-pressed="true"]{color:var(--paper);background:var(--ink)}button:focus-visible{outline:3px solid var(--blue);outline-offset:3px}.steps{display:flex;flex-direction:column;gap:10px}.steps p{font-size:16px;color:var(--muted);margin-top:10px}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:20px}.comparison img{width:100%;height:auto;border:1px solid var(--rule);aspect-ratio:3/2}.comparison p{font-size:16px}table{border-collapse:collapse;width:100%;font-size:16px}td,th{text-align:left;vertical-align:top;padding:14px 16px 14px 0;border-bottom:1px solid var(--rule)}td:first-child{font-weight:650;width:22%}th{font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.motion{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;margin:25px 0}.motion b{display:block;font-size:20px;margin-bottom:7px}.motion p{font-size:16px}.small{font-size:14px;color:var(--muted)}details{margin:20px 0}summary{font-weight:600;cursor:pointer}textarea{display:block;width:100%;height:170px;resize:vertical;padding:16px;background:transparent;font:16px/1.5 inherit;color:var(--ink);border:1px solid var(--rule);margin:15px 0}.recommendation{font-size:23px;line-height:1.45;max-width:60ch;margin-bottom:25px}footer{border-top:1px solid var(--rule);padding-top:25px;color:var(--muted);font-size:14px}nav{display:flex;gap:20px;flex-wrap:wrap;font-size:15px;margin-top:20px}@media(max-width:800px){main{padding:30px 20px}.hero,.grid,.comparison,.ladder,.motion{grid-template-columns:1fr}.wide{grid-column:auto}.hero{gap:20px}.steps{flex-direction:row;flex-wrap:wrap}.steps p{width:100%}td,th{padding:10px 8px 10px 0}h2{font-size:26px}}
'''
body=f'''<header><p class="eyebrow">Science Slam · slide design study</p><h1>Let the connections<br>be the reveal.</h1><p class="intro">Keep the Strangelove poster as the comic frame. Give the scientific middle a quiet, consistent design so people can follow the same nine quantities as their connections appear.</p><nav><a href="#studies">Slide studies</a><a href="#ladder">Try the three reveals</a><a href="#imagegen">Where image generation helps</a></nav></header>
<div class="hero">{picture(Path('figures/bomb.jpg'),'Existing black-and-white poster of the speaker riding a Hessian bomb')}<div><p class="eyebrow">The anchor already exists</p><h2>Borrow its restraint.</h2><p>The poster can carry the grain, drama and absurdity. The middle borrows its large type and uncluttered composition. Keep the diagrams on plain backgrounds.</p><p>Use the same poster at the end as a callback. A second visual joke needs a reason to replace that recognition.</p><div class="palette"><span class="swatch"><i style="background:#f8f6f0"></i>Warm paper</span><span class="swatch"><i style="background:#20272d"></i>Ink</span><span class="swatch"><i style="background:#347eab"></i>New links</span></div></div></div>
<section id="studies"><h2>The middle, with less to read</h2><div class="grid"><article class="study">{picture(Path('designs/three-settings.svg'),'Three GEV curve changes above simple Level, Spread and Tail controls')}<h3>01 · Three settings</h3><p>The simple control shapes make “parameter” tangible. Reveal one curve and its label at a time. Keep the controls schematic; detailed instrument panels would add another object to explain.</p></article><article class="study">{picture(Path('designs/station-tokens.svg'),'Three stations carrying the same Level, Spread and Tail tokens')}<h3>02 · Reuse the same quantities</h3><p>The labels become tokens. Add Station B, then C. Point across one row. The next picture uses the same A–B–C and L–S–T order.</p></article></div><p class="small">These are design studies. The curves and matrix patterns remain illustrative; the station locations are fictional. The control pointers are metaphors, without numerical readings.</p></section>
<section id="ladder"><h2>The grid stays still</h2><div class="ladder"><img id="matrix" src="{frames[0]}" width="1536" height="1024" alt="Separate estimates: diagonal entries of a nine-by-nine Hessian"><div class="steps" role="group" aria-label="Hessian reveal"><button type="button" data-step="0" aria-pressed="true">1 · Each estimate</button><button type="button" data-step="1" aria-pressed="false">2 · Within stations</button><button type="button" data-step="2" aria-pressed="false">3 · Between stations</button><p id="step-note" aria-live="polite">A deliberate simplification: keep each estimate's own uncertainty and drop the couplings.</p><p>On stage: point to one block. Click. Pause. Let the audience notice what changed before explaining it.</p></div></div><div class="motion"><div><b>Recognition first</b><p>Keep the matrix size, station order and row positions identical through all three states.</p></div><div><b>Colour has a job</b><p>Use blue for the added cross-station blocks. Introduce the technical meaning in speech.</p></div><div><b>The joke gets space</b><p>“Those extra blue squares took several years.” Keep the picture still while that lands.</p></div></div></section>
<section><h2>What I would remove from the projected draft</h2><div class="comparison"><article>{picture(Path('figures/hessian-3.png'),'Previous slide with explanatory paragraph and technical footer')}<h3>Current working draft</h3><p>Helpful for reading and preparing. The paragraph, repeated parameter names and technical footer compete with the change in the matrix.</p></article><article>{picture(Path('designs/matrix-3.svg'),'Simplified slide with large matrix and short Between stations label')}<h3>Proposed stage version</h3><p>Short stage label, larger grid, same ordering. The scientific qualifications remain in the speaking notes.</p></article></div></section>
<section><h2>Carry that discipline through the talk</h2><table><thead><tr><th>Moment</th><th>Design</th><th>What you do</th></tr></thead><tbody><tr><td>Opening</td><td>Full poster; no extra subtitle, affiliation list or footer.</td><td>Let the image register. Establish your relationship with the Hessian.</td></tr><tr><td>Rainfall</td><td>One real flood photograph, with a discreet credit.</td><td>Connect the research to an experience the audience recognises.</td></tr><tr><td>Uncertainty</td><td>Two large peaks, two short labels. State that the horizontal axis now concerns parameter values.</td><td>Translate the Hessian's job in one sentence. Keep optimisation off stage.</td></tr><tr><td>Research reveal</td><td>One fixed grid; dark blocks first, blue blocks last.</td><td>Distinguish fitting three quantities together from modelling records affected together.</td></tr><tr><td>Ending</td><td>Return to the poster. The final line can be spoken; it need not appear as another full slide of text.</td><td>Deliver your chosen ending, hold the image, stop.</td></tr></tbody></table><p class="small">Use manual clicks and hard cuts for the first rehearsal. If motion later proves useful, keep it brief and limited to the new blocks. A fixed three-state build is already enough.</p></section>
<section id="imagegen"><h2>Would GPT image generation help?</h2><p class="recommendation">It has already helped where it matters most: the poster. I would spend the next effort on this visual continuity and the rehearsal.</p><table><thead><tr><th>Possible use</th><th>Judgement</th><th>Why</th></tr></thead><tbody><tr><td>Opening poster</td><td>Keep the existing one.</td><td>It gives you a recognisable visual identity and a joke without explanation.</td></tr><tr><td>Title-free closing variant</td><td>Potentially useful later.</td><td>It could let the rider and Hessian fill the frame after the title has already been introduced. The unchanged poster is a good default.</td></tr><tr><td>Storm illustration</td><td>Low priority.</td><td>The real flood photograph already motivates the problem. A generated scene adds little here and should remain clearly illustrative.</td></tr><tr><td>Curves, station labels, Hessian</td><td>Draw precisely as vectors.</td><td>The same entries and positions need to survive every reveal. These assets already have editable PNG/SVG exports.</td></tr><tr><td>Decorative backgrounds</td><td>Leave the diagrams plain.</td><td>Grain, instrument textures and extra motifs would compete with the small changes the audience needs to see.</td></tr></tbody></table><details><summary>Optional prompt for a title-free closing image</summary><p>Use the existing poster as the edit target. This prompt is prepared for later; no new image has been generated.</p><textarea id="prompt" readonly aria-label="Optional image editing prompt">{html.escape(prompt)}</textarea><button id="copy-prompt" type="button">Copy prompt</button><span id="copy-status" class="small" aria-live="polite"></span></details></section>
<footer>Separate design studies; the live deck and previous click-through draft are unchanged. Five new studies are supplied in PNG and SVG. Figure text bounds and the physical square dimensions of matrix cells were checked; browser layout and venue projection have not been measured. <a href="slide-design-assets.zip">Download design assets and source</a>.</footer>'''
script='''
const frames=FRAMES;
const descriptions=["Separate estimates: diagonal entries of a nine-by-nine Hessian","Within-station links: three diagonal blocks","Between-station links: additional adjacent blocks in blue"];
const notes=["A deliberate simplification: keep each estimate's own uncertainty and drop the couplings.","Three quantities fitted from one station record can have coupled estimates, even when station records are modelled separately.","Dependent rainfall records create cross-station couplings. The blue blocks mark those added links in this toy chain."];
function selectStep(step){const image=document.getElementById('matrix');image.src=frames[step];image.alt=descriptions[step];document.getElementById('step-note').textContent=notes[step];document.querySelectorAll('[data-step]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.step)===step)));}
document.querySelectorAll('[data-step]').forEach(button=>button.addEventListener('click',()=>selectStep(Number(button.dataset.step))));
document.getElementById('copy-prompt').addEventListener('click',async()=>{const box=document.getElementById('prompt');box.select();try{await navigator.clipboard.writeText(box.value);document.getElementById('copy-status').textContent=' Copied.';}catch{document.getElementById('copy-status').textContent=' Selected: press Cmd/Ctrl+C to copy.';}});
'''.replace('FRAMES',json.dumps(frames,ensure_ascii=False))
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Science Slam — slide design studies</title><style>'+styles+'</style></head><body><main>'+body+'</main><script>'+script+'</script></body></html>'
(out/'slide-design-board.html').write_text(page,encoding='utf-8')
(root/'work/design-board.js').write_text(script,encoding='utf-8')
files=list((out/'designs').glob('*'))+[out/'slide-designs.R',out/'slide-design-board.html']
with zipfile.ZipFile(out/'slide-design-assets.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in files:z.write(p,p.relative_to(out))
with zipfile.ZipFile(out/'slide-design-assets.zip') as z:assert z.testzip() is None
print('Created self-contained visual board and design archive:',len(files),'files.')
